{
  "findings": [
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks a lifecycle configuration",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket has no lifecycle rule, so incomplete multipart uploads can persist indefinitely and consume storage."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "bucket_2" {
  bucket = "roger-bucket-2"
  acl    = var.bucket_acl

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.my_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }

  lifecycle_rule {
    id                                     = "abort-incomplete-multipart-uploads"
    enabled                                = true
    abort_incomplete_multipart_upload_days = 7
  }
}
",
  "fix_summary": "Added a lifecycle rule that removes incomplete multipart uploads after seven days. The existing customer-managed KMS encryption configuration was retained."
}
